<?php
declare(strict_types=1); require_once __DIR__.'/../includes/functions.php'; require_member();
if($_SERVER['REQUEST_METHOD']!=='POST') redirect('member/books.php'); verify_csrf();
$bookId=(int)post('book_id');$pickup=post('pickup_date');$days=(int)post('rental_days');$allowed=[date('Y-m-d'),date('Y-m-d',strtotime('+1 day'))];
if(!in_array($pickup,$allowed,true)||!valid_days($days)){flash('วันรับหรือระยะเวลาเช่าไม่ถูกต้อง','error');redirect('member/books.php');}
$pdo=db();try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT status FROM books WHERE id=? FOR UPDATE');$s->execute([$bookId]);$book=$s->fetch();$a=$pdo->prepare("SELECT COUNT(*) FROM reservations WHERE book_id=? AND status IN('pending','approved')");$a->execute([$bookId]);if(!$book||$book['status']!=='available'||$a->fetchColumn())throw new RuntimeException('หนังสือเล่มนี้ไม่พร้อมให้จอง');$due=date('Y-m-d',strtotime("$pickup +$days days"));$pdo->prepare("INSERT INTO reservations(user_id,book_id,pickup_date,due_date,rental_days,status) VALUES(?,?,?,?,?,'pending')")->execute([current_user()['id'],$bookId,$pickup,$due,$days]);$id=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE books SET status='reserved' WHERE id=?")->execute([$bookId]);log_activity('reserve','reservation',$id);$pdo->commit();flash('ส่งคำขอจองสำเร็จ กรุณารอผู้ดูแลอนุมัติ');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('member/my-rentals.php');
